   FROM SDesk_Cat      C ,
        SDesk_SubCat   SC,
        Phs_Cod_Status ST,
        Phs_Cod_Status CT
  WHERE C.Id        =SC.Cat_Id
    AND C.Status_Id =ST.Id
    AND SC.Status_Id=CT.Id;

