        VT.Subject     , VT.Description  , VT.dDate      , VT.SDate       ,
        VT.User_Id     , VT.User_Name    , VT.Side_Id    , VT.Side_Name   ,
        VT.EDate       , VT.Conv_Id      , VT.MsgDate    , VT.RecDate     ,
        VT.Msg         ,
        VT.RUser_Date  , VT.SUser_Date   , VT.SLA_date   , VT.CUser_Date  ,
        SC.Id         Chnge_Id      ,
