        VT.EDate       , VT.Conv_Id      , VT.MsgDate    , VT.RecDate     ,
        VT.Msg         ,
        VT.RUser_Date  , VT.SUser_Date   , VT.SLA_date   , VT.CUser_Date  ,
        CS.Id           Chnge_Id          ,  
        TC.Id           Chnge_oStatus_Id  , TC.Name         Chnge_oStatus_Name,
        CS.oStatus_Date Chnge_oStatus_Date,                                              
